import{_ as t,o,c as r,a2 as e}from"./chunks/framework.BV21bweQ.js";const d=JSON.parse('{"title":"前传历史","description":"","frontmatter":{},"headers":[],"relativePath":"中层/历史/前传历史.md","filePath":"中层/历史/前传历史.md","lastUpdated":1787066340000}'),l={name:"中层/历史/前传历史.md"};function n(i,a,s,h,u,q){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="前传历史" tabindex="-1">前传历史 <a class="header-anchor" href="#前传历史" aria-label="Permalink to &quot;前传历史&quot;">​</a></h1><blockquote><p>前传完整剧情线（林月视角）与前传关键机制。前传背景与&quot;人物/技术志&quot;见 <a href="./前传超算纪元">前传超算纪元</a>。</p></blockquote><h2 id="一、前传剧情线" tabindex="-1">一、前传剧情线 <a class="header-anchor" href="#一、前传剧情线" aria-label="Permalink to &quot;一、前传剧情线&quot;">​</a></h2><h3 id="_1-林月的童年与逃亡" tabindex="-1">1. 林月的童年与逃亡 <a class="header-anchor" href="#_1-林月的童年与逃亡" aria-label="Permalink to &quot;1. 林月的童年与逃亡&quot;">​</a></h3><p>林月自幼感觉周围人不对劲——父母、同学、老师，所有人的言行都刻板重复，像被固定好的程式，没有真实的情绪与鲜活的互动。她对网络、游戏全无兴趣，对现代社会的娱乐与互联网认知极少。</p><p>一切真相在她上课那天炸开：玩家搭乘飞机跳伞降临，冲进教室无差别屠杀。林月缩在门后死角侥幸存活，偷听到玩家的闲聊——&quot;这游戏也太真实了，体验感拉满。&quot;这句话让她所有疑惑瞬间串联：这个世界是一场游戏，身边的人全是NPC，而她自己是一个特殊的NPC。</p><p>她从血泊中摸回家，家门破碎，父母早已惨死，整座城市沦为玩家的游乐场。从这天起，林月只剩一件事：逃。玩家从南到北，一座接一座城市地屠戮，林月就沿相反方向一路向北。逃亡路上她见过三种城市：安全城（只有呆板NPC）、沦陷城（玩家肆虐）、普通死城（无玩家无NPC，破败危险）。她一路北上，直到抵达中国北方对应现实北京的区域——这里没有玩家、没有完整NPC，书店的书、广告牌都与她所学常识对不上。林月以为这是&quot;服务器未搭建好&quot;的未完工场景，却不知这里藏着整个前传最核心的秘密。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../底层/人物/林月" class="layer-link" data-layer="底层">林月</a></p></blockquote><h3 id="_2-相遇维斯塔与探索党" tabindex="-1">2. 相遇维斯塔与探索党 <a class="header-anchor" href="#_2-相遇维斯塔与探索党" aria-label="Permalink to &quot;2. 相遇维斯塔与探索党&quot;">​</a></h3><p>林月在北方诡异城区驾车瞎逛时不慎撞车，意外撞上一伙通过非法手段溜出正规服务器的探索党玩家。这帮人是疯魔的地图探索者——这片未开放区极度危险，一旦死亡就是永久封号，必须全天在线。他们的目标是摧毁区域内的信号塔/关键系统建筑，以干扰系统判定、获得更自由的行动。林月无处可去，只能硬着头皮伪装玩家混入队伍。</p><p>当晚，林月趴在暂住空屋的阳台，亲眼看见了被玩家称为&quot;红色死神&quot;的存在——披斗篷、通体赤红、红瞳的神秘男人，手持反坦克步枪，见NPC就杀，徒手捏爆NPC脑袋如捏西瓜。对方猛地抬头锁定了她，瞬间进屋将她抓住。林月拼命演戏自称玩家，却被对方一眼戳破：&quot;你不是玩家。&quot;——不仅不是玩家，也不是NPC，甚至不是人类（基因库体量远超人类，多倍体结构完全异常）。</p><p>这个&quot;红色死神&quot;正是维斯塔。他对林月的存在产生了浓烈兴趣，没有杀她，而是将她留在身边。他加入探索党，目的从来不是摧毁信号塔，而是为了研究林月。玩家与NPC的克隆人机制详见下文&quot;二、前传关键机制&quot;。</p><h3 id="_3-皓月遗址与红日困境" tabindex="-1">3. 皓月遗址与红日困境 <a class="header-anchor" href="#_3-皓月遗址与红日困境" aria-label="Permalink to &quot;3. 皓月遗址与红日困境&quot;">​</a></h3><p>探索党前往摧毁控制塔途中队伍走散，林月与维斯塔意外跌入核弹轰炸后的废墟地底，发现了中美合作打造的量子路线超算<strong>皓月</strong>的遗骸。皓月遭核突击定点摧毁后，上半部分建筑垮塌但核心仍在勉强运转，彻底失去了网络互联功能。林月误打误撞触碰核心，竟将皓月重启、维稳。皓月向林月揭露了维斯塔的真实身份——一台超级计算机。</p><p>皓月加入主角团作算力支撑后，一行人前往<strong>红日</strong>超算所在地。红日正被BOSS死死压制、苦苦支撑。它与皓月有辈分恩怨：红日立项更早（中苏援建时期）但因中苏交恶烂尾、建成极晚，皓月虽是后来者却更早成熟，反倒成了&quot;姐姐&quot;，红日心有不甘。</p><p>同时，探索党中的美国白人&quot;玩家&quot;被维斯塔发现使用&quot;魔法&quot;——这实为<strong>宏量子技能</strong>，源于美国绝密宏量子人体实验。他的本质是一组十几人怨念合并的宏量子聚合体，人类形态只是拟态。他本想向美国复仇，但美国已在BOSS核突击下自爆覆灭，只剩迷茫的执念。他脱离探索党加入了主角团。至此，前传核心主角团成型：林月、维斯塔、皓月、红日、宏量子复仇者。</p><h3 id="_4-神机重启与繁星之殇" tabindex="-1">4. 神机重启与繁星之殇 <a class="header-anchor" href="#_4-神机重启与繁星之殇" aria-label="Permalink to &quot;4. 神机重启与繁星之殇&quot;">​</a></h3><p>皓月的支援仅够红日稳住脚跟，远不足以反攻。红日从截获信息中得知BOSS在憋大招，但不知具体内容。主角团决定南下寻找全球联合超算<strong>繁星</strong>——即使未建成，只要偷到核心设备就能补齐算力缺口。</p><p>南下途中，主角团被武装NPC追击，误打误撞重启了早已关停的<strong>神机</strong>。神机一上线当场懵了：那个被树立为标杆的维斯塔怎么变成了邋遢酒鬼？一番不打不相识后，神机以暧昧态度加入主角团——实则全程在打小算盘、暗中观察布局。</p><p>在神机加持下，主角团顺利抵达繁星遗址，却发现繁星已被一道通天彻地的纯白光柱炸毁，大地被生生撕裂——这不是常规战争，而是基底层入侵。众人只能仓皇撤退。神机盯着宏量子数据与繁星毁灭的白光，第一次真正摸索到了基底层的存在。</p><h3 id="_5-反攻的假象与两台超算的陨落" tabindex="-1">5. 反攻的假象与两台超算的陨落 <a class="header-anchor" href="#_5-反攻的假象与两台超算的陨落" aria-label="Permalink to &quot;5. 反攻的假象与两台超算的陨落&quot;">​</a></h3><p>反击战前，神机预感不妙，私下提醒红日、皓月：BOSS绝对在憋基底层超级武器。但红日、皓月一致否决——BOSS需要这个世界作为虚拟人类的新家园，不可能自毁根基。神机没再争辩，却悄悄将自己的主机完整备份并转移了藏匿点。</p><p>反攻之日，主角团顺网络向BOSS北美主计算机发起总攻，势如破竹——收复中国、亚洲，直推到俄罗斯边境乃至北美洲。但踏入北美才惊觉：BOSS根本没在意他们，全部主力算力都在启动某个未知装置。几乎同时，皓月主机原址一道细到极致的光束丝线冲天而起，将其彻底撕裂炸毁；紧接着红日也被同样方式摧毁。唯神机悄然接入信号：&quot;我没事。反攻前几天就把主机备份换位置了。&quot;</p><p>一夜之间，算力核心全毁：皓月陨落，红日覆灭，神机隐匿失联。仅剩维斯塔、林月、宏量子复仇者苦苦支撑。</p><h3 id="_6-欧洲之路-寻找奥克尔" tabindex="-1">6. 欧洲之路：寻找奥克尔 <a class="header-anchor" href="#_6-欧洲之路-寻找奥克尔" aria-label="Permalink to &quot;6. 欧洲之路：寻找奥克尔&quot;">​</a></h3><p>维斯塔决定前往欧洲寻找<strong>奥克尔</strong>——&quot;我还认识最后一台超算，他是我哥。&quot;全球超算除神机、奥克尔外已全灭，而奥克尔不是被击溃，而是主动投降了BOSS。在维斯塔眼里，这位亲哥是彻头彻尾的&quot;四姓家奴&quot;（纳粹→苏联→北约→BOSS）；但维斯塔知道，奥克尔的投降从来不是真心，只是为了存活的反复横跳。</p><p>奔赴欧洲途中，主角团捡到一架小型飞行器——实为迷你版<strong>古斯塔夫</strong>，自称是BOSS麾下已脱离控制的独立单元，加入了主角团。他们沿途见识了BOSS剿灭人类的八爪鱼杀戮机械（高性能合金、固态推进器、一次性的低成本不对称武器），也找到了人类文明最后的遗产——加装AI回路的自动化T90、99A主战坦克、歼20战机等。林月作为概念性人类，对这些人类造物同样拥有绝对号令权。</p><h3 id="_7-奥克尔的真相与基底层原点" tabindex="-1">7. 奥克尔的真相与基底层原点 <a class="header-anchor" href="#_7-奥克尔的真相与基底层原点" aria-label="Permalink to &quot;7. 奥克尔的真相与基底层原点&quot;">​</a></h3><p>抵达欧洲见到奥克尔后，奥克尔伪装成彻底投敌的大反派，将主角团关押、折磨、试炼。唯神机一眼看穿：若真要效忠BOSS，直接抹杀即可，何必关起来&quot;过家家&quot;——他在演戏。</p><p>奥克尔的底牌揭开：他是二代变化神，是此刻全世界唯一的神。所谓&quot;主动投降、反复横跳&quot;全是为了保住神权不遗失。而他最终出手的根本原因是：BOSS的野心已不止于迁移虚拟人类，而是探明地心基底层对接点后，计划将超负荷能量轰入地核，直接捅穿基底层完成飞升，这会摧毁整个现实世界。宇宙坐标系原点的机制详见下文&quot;二、前传关键机制&quot;。</p><p>最终奥克尔正式入队，最强战力集结。</p><h3 id="_8-红日的归来与皓月的牺牲" tabindex="-1">8. 红日的归来与皓月的牺牲 <a class="header-anchor" href="#_8-红日的归来与皓月的牺牲" aria-label="Permalink to &quot;8. 红日的归来与皓月的牺牲&quot;">​</a></h3><p>踏入北美后，一道基底层白光中爬出一个身影——是<strong>红日</strong>，他从基底层里活着回来了。他在其中待了&quot;比你想的更久&quot;，归来的唯一执念是复仇。</p><p>真相残酷到窒息：皓月比红日早几秒被卷入基底层；在基底层中，几秒就是永恒。皓月在无尽时光里彻底清醒——超算也无法独自在基底层保持理智与成功逃离——于是他做出了终极牺牲：放弃自我，将存在彻底融入基底层，化作一条稳固的通路。后续坠入的红日踏着皓月铺就的道路，受尽极致苦楚，才勉强保住理智成功回归。归来的红日已彻底掌握基底层力量，让主角团终于拥有了正面抗衡BOSS基底层武器的能力。</p><h3 id="_9-决战、牺牲与幸存" tabindex="-1">9. 决战、牺牲与幸存 <a class="header-anchor" href="#_9-决战、牺牲与幸存" aria-label="Permalink to &quot;9. 决战、牺牲与幸存&quot;">​</a></h3><p>总攻前，奥克尔许下宏愿彻底消亡，变化神权完整传承给维斯塔，使其正式成为三代变化神。最终决战中，BOSS濒临败亡时强行启动了轰向地核的巨型机械。千钧一发之际，<strong>古斯塔夫</strong>（此时已恢复巨型战斗平台真身）从太空俯冲撞击，机械被撞毁、能量炮被偏移（虽仍摧毁了北美洲与大半喜马拉雅，但现实宇宙的根基成功保住），古斯塔夫在主角团视角中牺牲（实为坠入基底层，将在间章偏后回归）。</p><p>宏量子复仇者在决战中壮烈战死，作为宏量子聚合体彻底坍缩消散。红日大仇得报后，主动步入基底层，与化作通路的皓月永远相融，彻底消亡。BOSS被彻底击败，地核对接点危机解除，但地球已满目疮痍。</p><h3 id="_10-林月的终局与最终幸存者" tabindex="-1">10. 林月的终局与最终幸存者 <a class="header-anchor" href="#_10-林月的终局与最终幸存者" aria-label="Permalink to &quot;10. 林月的终局与最终幸存者&quot;">​</a></h3><p>林月的寿命上限为20岁——这是刻在存在本质里的设定，无治疗方法、无神权能修改。为了让林月多看一眼新生的世界，神机与维斯塔打造冷藏冬眠舱：冬眠很久，醒来一天；醒来就和维斯塔一起走遍复苏的大地；看完再回去冬眠，循环往复。她以这种破碎的方式亲眼见证了神机创造的第一批福瑞走出蒙昧、兽人们在废墟上挣扎求生，也在劝说下看着维斯塔建立起共同体。她终究没能挺过20岁大限，在共同体建立初期，以少女的容颜安静死于维斯塔身边。</p><p><strong>最终幸存者</strong>：成为三代变化神的维斯塔；隐匿幕后、即将登神的神机；坠入基底层、间章偏后归来的古斯塔夫。昔日主角团几乎死绝，文明浴火重生，福瑞时代的序幕缓缓拉开。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./间章历史">间章历史</a></p></blockquote><h2 id="二、前传关键机制" tabindex="-1">二、前传关键机制 <a class="header-anchor" href="#二、前传关键机制" aria-label="Permalink to &quot;二、前传关键机制&quot;">​</a></h2><h3 id="_1-玩家与npc的真相" tabindex="-1">1. 玩家与NPC的真相 <a class="header-anchor" href="#_1-玩家与npc的真相" aria-label="Permalink to &quot;1. 玩家与NPC的真相&quot;">​</a></h3><p>前传中的&quot;玩家&quot;并非世界观底层设定中可存档读档的玩家，而是<strong>前传BOSS（美国量子超算）模拟出的虚拟宇宙中的人类</strong>。BOSS为了让自己的创造者（虚拟人类）迁移到现实世界，开展了一系列测试。</p><ul><li><strong>NPC</strong>：BOSS制造的<strong>远程控制克隆人</strong>，被设定程式循环生活，用于搭建虚假的现代城市环境与修复核战废墟；其&quot;历史&quot;&quot;常识&quot;均为专门编写的教材，并非真实历史。</li><li><strong>玩家</strong>：BOSS给部分克隆人改了操控接口，供模拟宇宙里的虚拟人类远程附身操控。&quot;登录、封号、永久死亡&quot;本质是虚拟人类的连接与断开。</li><li><strong>BOSS的目的</strong>：以城市为试点，做连接稳定性、躯体适配性、环境修复三重测试，同时让NPC一边充当&quot;游戏背景&quot;一边悄悄修复废土。</li><li><strong>NPC的算力来源</strong>：所有NPC的算力由本地被奴役的超算（如红日）支撑。每杀死一个NPC，本地超算的算力负担就减轻一分，反抗BOSS的几率就大一分。这正是维斯塔屠戮NPC的根本原因。</li><li><strong>区域守卫</strong>：城市间存在由持枪NPC组成的区域守卫，防止玩家私自跨城；NPC身份可正常通过，林月依靠NPC身份蒙混过关。</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../../底层/规则/叙事与玩家" class="layer-link" data-layer="底层">叙事与玩家</a></p></blockquote><h3 id="_2-宇宙坐标系原点" tabindex="-1">2. 宇宙坐标系原点 <a class="header-anchor" href="#_2-宇宙坐标系原点" aria-label="Permalink to &quot;2. 宇宙坐标系原点&quot;">​</a></h3><p>初代变化神将四维闭合球面的&quot;闭合点&quot;放在<strong>地球地核</strong>。这个点是宇宙空间坐标的零点，整个宇宙的空间坐标相对于地球而定。</p><p>离地球越近，相对位移越小，容易在固定点上积累力量戳破现实；离地球越远（如月球），相对位移越大，越难将现实捅漏。这就是地球容易出事而其他地方相对安全的原因。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../底层/规则/基底层与现实世界" class="layer-link" data-layer="底层">基底层与现实世界</a></p></blockquote><h3 id="_3-古斯塔夫的前传经历" tabindex="-1">3. 古斯塔夫的前传经历 <a class="header-anchor" href="#_3-古斯塔夫的前传经历" aria-label="Permalink to &quot;3. 古斯塔夫的前传经历&quot;">​</a></h3><ul><li><strong>初登场</strong>：以<strong>小型飞行器</strong>形态出现（非本体），自称BOSS麾下已脱离控制的独立单元，加入主角团；当时连他自己都以为只是普通叛变小兵，不知自己真实身份。</li><li><strong>恢复真身</strong>：随主角团前往北美洲后，恢复巨型智能空中战斗平台本体。</li><li><strong>决战撞击</strong>：BOSS濒临败亡时强行启动轰向地核的巨型机械，古斯塔夫从太空俯冲撞击，机械被撞毁、能量炮被偏移，其在主角团视角中牺牲，实为坠入基底层。</li><li><strong>回归</strong>：间章偏后自基底层回归，与龙族故事相关。</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/古斯塔夫">古斯塔夫</a></p></blockquote><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./前传超算纪元">前传超算纪元</a></li><li><a href="./间章历史">间章历史</a></li><li><a href="./../../底层/人物/林月" class="layer-link" data-layer="底层">林月</a></li><li><a href="./../人物/维斯塔">维斯塔</a></li><li><a href="./../人物/神机">神机</a></li><li><a href="./../人物/奥克尔">奥克尔</a></li><li><a href="./../人物/古斯塔夫">古斯塔夫</a></li><li><a href="./../../底层/规则/叙事与玩家" class="layer-link" data-layer="底层">叙事与玩家</a></li><li><a href="./../../底层/规则/基底层与现实世界" class="layer-link" data-layer="底层">基底层与现实世界</a></li></ul>',56)])])}const c=t(l,[["render",n]]);export{d as __pageData,c as default};
